namespace SizarDev\Utils;

require_once __DIR__ . '/MachineFingerprint.php';

/**
 * Pure Native PHP TOTP (Time-Based One-Time Password) Cryptographic Engine
 * Compliant with RFC 6238 (TOTP) and RFC 3548 / RFC 4648 (Base32).
 *
 * Zero external Composer dependencies.
 * Features hardware-bound AES-256-GCM authenticated encryption at rest.
 */
class Totp
{
    private const BASE32_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

    /**
     * Generate a cryptographically secure random Base32 secret key.
     * Default length: 32 characters (160 bits of entropy), standard RFC 6238 Section 4 recommendation.
     * Preserves backward compatibility for existing 16-character keys.
     */
    public static function generateSecret(int $length = 32): string
    {
        $alphabet = self::BASE32_CHARS;
        $alphabetLen = strlen($alphabet);
        $secret = '';
        $randomBytes = random_bytes($length);

        for ($i = 0; $i < $length; $i++) {
            $secret .= $alphabet[ord($randomBytes[$i]) % $alphabetLen];
        }

        return $secret;
    }

    /**
     * Decode a Base32 string into raw binary bytes.
     */
    public static function base32Decode(string $b32): string
    {
        $b32 = strtoupper(trim($b32));
        $alphabet = self::BASE32_CHARS;
        $binaryString = '';

        $len = strlen($b32);
        for ($i = 0; $i < $len; $i++) {
            $char = $b32[$i];
            if ($char === '=' || $char === ' ' || $char === '-') {
                continue;
            }
            $val = strpos($alphabet, $char);
            if ($val === false) {
                continue;
            }
            $binaryString .= str_pad(decbin($val), 5, '0', STR_PAD_LEFT);
        }

        $octets = str_split($binaryString, 8);
        $output = '';
        foreach ($octets as $octet) {
            if (strlen($octet) === 8) {
                $output .= chr(bindec($octet));
            }
        }

        return $output;
    }

    /**
     * Calculate 6-digit TOTP code for a given Base32 secret and time slice.
     */
    public static function calculateCode(string $secret, ?int $timeSlice = null): string
    {
        if ($timeSlice === null) {
            $timeSlice = (int) floor(time() / 30);
        }

        $secretBytes = self::base32Decode($secret);

        // Pack 64-bit integer into 8 bytes big-endian
        $timeBytes = pack('N*', 0) . pack('N*', $timeSlice);

        // Calculate HMAC-SHA1
        $hmac = hash_hmac('sha1', $timeBytes, $secretBytes, true);

        // Dynamic truncation (RFC 4226 / RFC 6238)
        $offset = ord(substr($hmac, -1)) & 0x0F;
        $hashPart = substr($hmac, $offset, 4);
        $value = unpack('N', $hashPart)[1] & 0x7FFFFFFF;

        return str_pad((string)($value % 1000000), 6, '0', STR_PAD_LEFT);
    }

    /**
     * Verify a submitted 6-digit TOTP code against a secret key.
     * Checks current time window +/- $discrepancy (default: 1 step = +/- 30s) to account for clock drift.
     * Optionally populates $matchedSlice with the exact time window step that matched.
     */
    public static function verify(string $secret, string $code, int $discrepancy = 1, ?int &$matchedSlice = null): bool
    {
        $code = trim($code);
        if (!preg_match('/^[0-9]{6}$/', $code)) {
            return false;

