        }

        $currentSlice = (int) floor(time() / 30);
        $discrepancy = max(0, min(5, $discrepancy));

        for ($i = -$discrepancy; $i <= $discrepancy; $i++) {
            $slice = $currentSlice + $i;
            $calculated = self::calculateCode($secret, $slice);
            if (hash_equals($calculated, $code)) {
                $matchedSlice = $slice;
                return true;
            }
        }

        return false;
    }

    /**
     * Derive a 256-bit AES encryption key bound to the server's physical machine fingerprint.
     */
    private static function getEncryptionKey(): string
    {
        $machineId = \MachineFingerprint::getMachineId();
        return hash_hkdf('sha256', $machineId, 32, 'sizar-2fa-totp-aes-key', 'sizar-pos-master-salt');
    }

    /**
     * Encrypt a plaintext Base32 secret using AES-256-GCM.
     * Returns a compact, authenticated base64 string.
     */
    public static function encryptSecret(string $plainSecret): string
    {
        $key = self::getEncryptionKey();
        $iv = random_bytes(12); // Standard 96-bit IV for GCM
        $tag = '';

        $cipherText = openssl_encrypt(
            $plainSecret,
            'aes-256-gcm',
            $key,
            OPENSSL_RAW_DATA,
            $iv,
            $tag,
            'sizar_totp_auth_data',
            16
        );

        if ($cipherText === false) {
            throw new \RuntimeException('Failed to encrypt TOTP secret');
        }

        // Pack: IV (12 bytes) + Tag (16 bytes) + CipherText
        return base64_encode($iv . $tag . $cipherText);
    }

    /**
     * Decrypt an AES-256-GCM encrypted Base32 secret.
     * Returns null if tampering detected, corrupted, or invalid key.
     */
    public static function decryptSecret(?string $encrypted): ?string
    {
        if (empty($encrypted)) {
            return null;
        }

        $raw = base64_decode($encrypted, true);
        if ($raw === false || strlen($raw) < 28) {
            return null;
        }

        $iv = substr($raw, 0, 12);
        $tag = substr($raw, 12, 16);
        $cipherText = substr($raw, 28);
        $key = self::getEncryptionKey();

        $plain = openssl_decrypt(
            $cipherText,
            'aes-256-gcm',
            $key,
            OPENSSL_RAW_DATA,
            $iv,
            $tag,
            'sizar_totp_auth_data'
        );

        return ($plain !== false) ? $plain : null;
    }

    /**
     * Construct dynamic TOTP URI for mobile authenticator QR Code scanning.
     */
    public static function getOtpAuthUri(string $username, string $storeName, string $secret): string
    {
        $cleanStore = trim($storeName) !== '' ? trim($storeName) : 'Sizar POS';
        $cleanUser = trim($username) !== '' ? trim($username) : 'Cashier';

        $issuer = rawurlencode($cleanStore);
        $account = rawurlencode($cleanUser);
        $sec = rawurlencode(strtoupper(trim($secret)));

        return "otpauth://totp/{$issuer}:{$account}?secret={$sec}&issuer={$issuer}&algorithm=SHA1&digits=6&period=30";
